import {PALETTE} from './core.js';
export function line(ctx,x1,y1,x2,y2,color){
  ctx.fillStyle=color;let x=Math.round(x1),y=Math.round(y1);const tx=Math.round(x2),ty=Math.round(y2),dx=Math.abs(tx-x),sx=x<tx?1:-1,dy=-Math.abs(ty-y),sy=y<ty?1:-1;let err=dx+dy;
  for(let guard=0;guard<5000;guard++){ctx.fillRect(x,y,1,1);if(x===tx&&y===ty)break;const e=2*err;if(e>=dy){err+=dy;x+=sx}if(e<=dx){err+=dx;y+=sy}}
}
export function poly(ctx,pts,color,close=false){for(let i=1;i<pts.length;i++)line(ctx,...pts[i-1],...pts[i],color);if(close)line(ctx,...pts.at(-1),...pts[0],color)}
export function orbit(ctx,x,y,r,color,ratio=1){const p=[];for(let a=0;a<=Math.PI*2+.1;a+=.07)p.push([x+Math.cos(a)*r,y+Math.sin(a)*r*ratio]);poly(ctx,p,color)}
export function star(ctx,x,y,r,color){const p=[];for(let i=0;i<10;i++){const a=i*Math.PI/5-Math.PI/2,d=i%2?r*.42:r;p.push([x+Math.cos(a)*d,y+Math.sin(a)*d])}poly(ctx,p,color,true)}
export function anchor(ctx,x,y,r,color){orbit(ctx,x,y-r*.7,r*.18,color);line(ctx,x,y-r*.5,x,y+r*.65,color);line(ctx,x-r*.5,y-r*.1,x+r*.5,y-r*.1,color);poly(ctx,[[x-r*.7,y+r*.12],[x-r*.62,y+r*.55],[x,y+r*.8],[x+r*.62,y+r*.55],[x+r*.7,y+r*.12]],color);line(ctx,x-r*.7,y+r*.12,x-r*.85,y+r*.32,color);line(ctx,x+r*.7,y+r*.12,x+r*.85,y+r*.32,color)}
const ICONS={
 oracle:['0000000000000000','0000000500000000','0000005550000000','000005F5F5000000','000055FFF5500000','0005555555550000','0000055555000000','000005F5F5000000','000005F5F5000000','000005F5F5000000','0005555555550000','005FFFFFFFFF5000','0555555555555500','0000000000000000'],
 atlas:['0000000110000000','0000011331100000','000113B33B311000','00133B3B3B3B3100','013B3B3333B3B310','0133333113333310','0133B311113B3310','0133333113333310','0013B3B33B3B3100','000113B33B311000','0000011331100000','0000000110000000'],
 crew:['000C00000000C000','000CC000000CC000','000C4C0000C4C000','000C44CCCC44C000','000C44CCCC44C000','000CCCCCCCCCC000','000CCF1CC1FCC000','000CCCFFFFCCC000','0000CCCFFCCC0000','00000CC11CC00000','000000CCCC000000','0000000CC0000000'],
 workshop:['0000002222222000','000002A22222A200','00002A2AAAA2AA20','0002A2AAAA2AAA20','002A2AAAA2AAAA20','0002A2AAAA2AAA20','00002A2AAAA2AA20','000002A22222A200','0000002222222000'],
 logbook:['0000666666666600','0006E6FFFFFFF600','0006E6F77777F600','0006E6FFFFFFF600','0006E6F77777F600','0006E6FFFFFFF600','0006E6F77777F600','0006E6FFFFFFF600','0006E66666666600','0006666666666600'],
 shell:['0011111111111100','001FFFFFFFFFF100','001F1FFFFFFFF100','001FF1FFFFFFF100','001FFF1FFFFFF100','001FF1FFFFFFF100','001F1FF1111FF100','001FFFFFFFFFF100','0011111111111100'],
 mora:['0000001111000000','000011BBBB110000','0001BBFFFFBB1000','001BF1FFFF1FB100','001BFFFFFFFFB100','0001FF1FF1FF1000','00001FFFFFF10000','0000011111100000','0001333333331000','0013333FF3333100','013333FFFF333310'],
 sandhi:['0000000550000000','0000005DD5000000','000005DDDD500000','0000005DD5000000','000005DDDD500000','00005D5DD5D50000','0005D05DD50D5000','0000005DD5000000','000005D55D500000','00005D5005D50000','0005D500005D5000'],
 engineer:['0000066666000000','000066EEEE600000','0006EE666EE60000','0006E66116E60000','00066EE11EE60000','0000666666600000','0006666EE6666000','0066EE6EE6EE6600','0066EE6666EE6600','0000666006660000','0000666006660000'],
 genno:['0000008888000000','000008FFFF800000','000008F00F800000','0000008FF8000000','0000008888000000','000008EEEE800000','00008EE88EE80000','0008EE8888EE8000','008EEE8888EEE800','0008888888888000'],
 mycelium:['0000002222000000','000022AAAA220000','0002AAFAFAAA2000','002AFAAAAFAAA200','0022222222222200','0000006EE6000000','0000006EE6000000','0000006EE6000000','0000066666600000','0000202002020000','0002002000202000'],
 mesh:['0000011111100000','00001F1FF1F10000','0001F111111F1000','001F1F1FF1F1F100','0011111111111100','001F1F1FF1F1F100','0001F111111F1000','00001F1FF1F10000','0000011111100000']
};
export function icon(canvas,name){const c=canvas.getContext('2d');c.clearRect(0,0,16,16);const pattern=ICONS[name]||ICONS.atlas;for(let y=0;y<pattern.length;y++)for(let x=0;x<pattern[y].length;x++){const n=parseInt(pattern[y][x],16);if(n){c.fillStyle=PALETTE[n];c.fillRect(x,y,1,1)}}}
export function vessel(canvas,t=0){
 const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.fillStyle='#fff';c.fillRect(0,0,w,h);
 c.fillStyle='#aaa';for(let x=12;x<w;x+=16)for(let y=12;y<h;y+=16)c.fillRect(x,y,1,1);
 const angle=.37+Math.sin(t*.24)*.17,roll=-.33;const project=(x,y,z)=>{const yy=y*Math.cos(angle)-z*Math.sin(angle),zz=y*Math.sin(angle)+z*Math.cos(angle);return [w*.47+(x*Math.cos(roll)-yy*Math.sin(roll))*.93,h*.48+(x*Math.sin(roll)+yy*Math.cos(roll))*.69+zz*.15]};
 for(let ring=0;ring<13;ring++){const x=-80+ring*11.5,r=Math.sin((ring+1)/14*Math.PI)*37,p=[];for(let i=0;i<=32;i++){const a=i*Math.PI/16;p.push(project(x,Math.cos(a)*r,Math.sin(a)*r*.6))}poly(c,p,ring%3===0?'#aa00aa':'#0000aa')}
 for(let j=0;j<8;j++){const a=j*Math.PI/4,p=[];for(let i=0;i<13;i++){const r=Math.sin((i+1)/14*Math.PI)*37;p.push(project(-80+i*11.5,Math.cos(a)*r,Math.sin(a)*r*.6))}poly(c,p,'#0000aa')}
 for(const side of [-1,1]){const edge=[];for(let i=0;i<=30;i++){const x=-84+i*5,r=Math.sin((i+1)/33*Math.PI)*45;edge.push(project(x,side*(r+Math.sin(i*.7+t*2)*5),0))}poly(c,edge,'#00aaaa');for(let i=0;i<30;i+=2){const x=-84+i*5,r=Math.sin((i+1)/33*Math.PI)*38;poly(c,[project(x,side*r,0),edge[i]],'#00aaaa')}}
 for(let arm=0;arm<8;arm++){const p=[];for(let j=0;j<=24;j++){const x=63+j*1.85,y=(arm-3.5)*3+Math.sin(j*.14+t+(arm*.7))*j*.28;p.push(project(x,y,Math.sin(arm)*10))}poly(c,p,arm%3===0?'#aa00aa':'#0000aa')}
 const eye=project(52,-17,-18);c.fillStyle='#0000aa';c.fillRect(Math.round(eye[0])-2,Math.round(eye[1])-2,4,4);c.fillStyle='#fff';c.fillRect(Math.round(eye[0]),Math.round(eye[1])-1,1,1);
 c.font='8px Shrine';c.fillStyle='#555';c.fillText('S.A. / CHITIN + BISMUTH',8,13);c.fillText('FIG. 01',w-64,h-6);c.fillStyle='#aa00aa';c.fillText('~',w-22,16);
}
export function waveform(canvas,t=0,detuned=true){const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.fillStyle='#fff';c.fillRect(0,0,w,h);c.fillStyle='#aaa';for(let y=6;y<h;y+=12)for(let x=0;x<w;x+=4)c.fillRect(x,y,1,1);for(const [phase,col,amp]of [[0,'#0000aa',14],[1.2,'#aa00aa',8]]){const p=[];for(let x=0;x<w;x++){const a=x*.078+t*(detuned?1.2:.6)+phase;p.push([x,h/2+Math.sin(a)*amp+Math.sin(a*.35+phase)*3])}poly(c,p,col)}}
export function shrine(canvas,t=0){const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.fillStyle='#0000aa';c.fillRect(0,0,w,h);for(let i=0;i<42;i++){const x=(i*67+11)%w,y=(i*37+7)%(h-50);c.fillStyle=i%3?'#5555ff':'#fff';c.fillRect(x,y,1,1)}for(let j=0;j<8;j++){const y=133+j*5,left=27-j*3;c.fillStyle=PALETTE[[5,13,11,3,14,6,13,15][j]];c.fillRect(left,y,w-left*2,3)}for(let j=0;j<7;j++){const left=48+j*2;c.strokeStyle=PALETTE[[13,5,11,3,14,13,15][j]];c.strokeRect(left+.5,68+j*3,w-2*left,68-j*3)}c.fillStyle='#0000aa';c.fillRect(66,93,42,40);poly(c,[[37,76],[w/2,43],[w-37,76]],'#ff55ff');poly(c,[[43,80],[w/2,49],[w-43,80]],'#55ffff');star(c,w/2,27,11,'#ffff55');anchor(c,w/2,111+Math.sin(t)*2,16,'#fff');c.fillStyle='#ff55ff';c.fillRect(33,82,6,49);c.fillRect(w-39,82,6,49);c.fillStyle='#55ffff';c.fillRect(36,82,2,49);c.fillRect(w-36,82,2,49)}
export function mapBackground(canvas){const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.fillStyle='#0000aa';c.fillRect(0,0,w,h);for(let i=0;i<100;i++){c.fillStyle=i%3?'#5555ff':'#00aaaa';c.fillRect((i*37+4)%w,(i*61+9)%h,1,1)}const p=[[11,82],[39,43],[98,26],[205,34],[256,62],[285,80],[256,108],[207,130],[84,140],[36,119],[11,82]];poly(c,p,'#55ffff');poly(c,p.map(([x,y])=>[150+(x-150)*.94,82+(y-82)*.9]),'#ff55ff');for(let x=42;x<260;x+=28)line(c,x,49,x,118,'#5555ff');for(const y of [64,86,108])line(c,29,y,270,y,'#5555ff')}
export function executeProgram(canvas,ops){const c=canvas.getContext('2d');let color='#0000aa',out=[];c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);for(const op of ops){const a=op.args;switch(op.name){case'Clear':c.fillStyle=PALETTE[a[0]];c.fillRect(0,0,canvas.width,canvas.height);break;case'Color':color=PALETTE[a[0]];break;case'Line':line(c,...a,color);break;case'Orbit':orbit(c,...a,color);break;case'Star':star(c,...a,color);break;case'Anchor':anchor(c,...a,color);break;case'Print':out.push(a[0]);break}}return out.join('\n')||`${ops.length} commands completed.`}
